INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 3, 'theory', 'Quiz: pointers and arrays');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 3, 0, 'What is the expression a[i] equivalent to for an array a?', '["&a + i", "a + *i", "(*a) + i", "*(a + i)"]', 3, 'Indexing is notation for shift and dereference: a + i moves the pointer by i elements (i * sizeof(*a) bytes), and the asterisk reads the object.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 3, 1, 'What is sizeof(a) inside a function void f(int a[])?', '["The size of a pointer (8 on a 64-bit machine)", "The size of the array in bytes", "The number of elements", "Zero"]', 0, 'An array parameter “decays” into a pointer to the first element, and the length information is lost; it is passed as a separate parameter.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 3, 2, 'What does const int *p mean?', '["The pointer itself cannot be changed, the data can", "The data cannot be changed through p, but the pointer can move", "Neither can be changed", "p points to the constant NULL"]', 1, 'Read right to left: p is a pointer to an int that is const. To forbid moving the pointer, write int *const p.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 3, 3, 'What is the right way to reinterpret the bits of a float as a uint32_t?', '["*(uint32_t *)&f, a pointer cast", "(uint32_t)f", "Via memcpy into a uint32_t variable", "Via void *"]', 2, 'A pointer cast violates strict aliasing (UB). memcpy copies the bytes, and the compiler turns it into a single instruction.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 3, 4, 'What does memmove(a + 1, a, 4 * sizeof a[0]) do for int a[5]?', '["Copies 4 bytes", "Shifts the first four elements one position to the right, safely for overlapping areas", "Copies everything to the beginning", "Nothing: the areas overlap"]', 1, 'memmove handles overlap and copies in the right direction; memcpy in this situation is undefined behavior. The size is always in bytes.');
